CREATE TABLE "HomeCarousel" (
    "id" TEXT NOT NULL DEFAULT 'homepage',
    "config" JSONB NOT NULL,
    "revision" INTEGER NOT NULL DEFAULT 1,
    "updatedAt" TIMESTAMP(3) NOT NULL,
    CONSTRAINT "HomeCarousel_pkey" PRIMARY KEY ("id")
);

INSERT INTO "HomeCarousel" ("id", "config", "revision", "updatedAt") VALUES ('homepage', '{"slides":[{"id":"origin","eyebrow":"The Story of Amaana · Hyderabad","title":"A trust that began around one family table.","description":"What began as a small grassroots effort to support families with dignity grew into recurring community programmes and a formally organised charitable foundation. Our purpose remains the same: treat every contribution as an amaana — a trust.","primaryLabel":"Discover our story","primaryHref":"/about","secondaryLabel":"Explore our work","secondaryHref":"/our-work","image":"origin","imageAlt":"Photo-based collage illustrating Amaana community programmes","focalX":50,"focalY":50,"order":0,"status":"PUBLISHED","startsAt":"","endsAt":"","appealSlug":""},{"id":"eid","eyebrow":"Ramadan & Eid · A recurring initiative","title":"Eid Gift Kits. Thoughtful support, year after year.","description":"Our Eid Gift Kits initiative brings practical essentials to families facing financial hardship, with care for their needs and dignity. Explore the programme’s history and its documented distributions across the years.","primaryLabel":"Explore Eid Gift Kits","primaryHref":"/our-work/eid-gift-kits","secondaryLabel":"Ways to support","secondaryHref":"/get-involved","image":"eid","imageAlt":"Photo-based collage of Amaana Eid Gift Kit preparation and distribution","focalX":50,"focalY":50,"order":1,"status":"PUBLISHED","startsAt":"","endsAt":"","appealSlug":""},{"id":"medical","eyebrow":"Medical & financial relief","title":"Verified help when a family needs it most.","description":"Illness and sudden financial hardship can become too heavy for a family to carry alone. Amaana reviews needs, protects personal information and connects responsible support with verified medical and financial assistance.","primaryLabel":"Explore medical & financial aid","primaryHref":"/programmes/medical-financial-relief","secondaryLabel":"Request assistance","secondaryHref":"/request-assistance","image":"medical","imageAlt":"Photo-based collage illustrating Amaana’s community assistance work","focalX":50,"focalY":50,"order":2,"status":"PUBLISHED","startsAt":"","endsAt":"","appealSlug":""},{"id":"taleem","eyebrow":"Amaana Taleem Initiative","title":"Helping learners continue with dignity.","description":"Amaana Taleem supports learning through educational essentials, Qur’anic education and verified sponsorship pathways. Discover the initiative and how sustained support can help learners continue their journey.","primaryLabel":"Explore Amaana Taleem","primaryHref":"/our-work/taleem","secondaryLabel":"Sponsor education","secondaryHref":"/get-involved/sponsor-education","image":"taleem","imageAlt":"Photo-based collage of the Amaana Taleem education initiative","focalX":50,"focalY":50,"order":3,"status":"PUBLISHED","startsAt":"","endsAt":"","appealSlug":""},{"id":"qurbani","eyebrow":"Qurbani · Sharing with care","title":"Qurbani Meat Distribution. Care that reaches families.","description":"Our recurring Qurbani programme shares meat with families through thoughtful preparation, local coordination and dignified distribution. Explore the main programme and its documented work across the years.","primaryLabel":"Explore Qurbani distribution","primaryHref":"/our-work/qurbani-meat-distribution","secondaryLabel":"Ways to support","secondaryHref":"/get-involved","image":"qurbani","imageAlt":"Photo-based collage of Amaana Qurbani meat packing and distribution","focalX":50,"focalY":50,"order":4,"status":"PUBLISHED","startsAt":"","endsAt":"","appealSlug":""}],"appealPosition":1}'::jsonb, 1, CURRENT_TIMESTAMP);
